// --------------------- GPU -------------------------------

__device__ long long getWordsValue(const char* key) {
    return wordMappings[(key[0] - 'a') * 676 + (key[1] - 'a') * 26 + (key[2] - 'a')];
}

__device__ void factorise(unsigned long long number, unsigned long long *sumOfPrimes){
    // where i < length of the lookup table
    for (int i = 0; i < 82025; i++)
    {
        int prime = primeNumbers[i];
        while (number % prime == 0)
        {
            *sumOfPrimes += prime;
            number /= prime;
            if (number == 1) return;
        }
    }
}

__global__
void processLogEntriesKernel(
    const unsigned long long *d_encryptedNumbers,
    const char *d_messageBuffer,
    const int numEntries,
    unsigned long long *d_finalResults,
    int *d_originalLineIndices
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numEntries)
        return;

    unsigned long long sumOfPrimeComponents = 0;
    factorise(d_encryptedNumbers[idx], &sumOfPrimeComponents);

    const char *message = d_messageBuffer + (idx * MAX_KEY_LEN);

    unsigned long long transformedKey = getWordsValue(message);

    unsigned long long finalValue = sumOfPrimeComponents * transformedKey;
    
    d_finalResults[idx] = finalValue;
    d_originalLineIndices[idx] = idx;
}

// ----------------------------- CPU --------------------------

char* generateKey(const char* input) {
    static char key[4];
    int count = 0;
    const char* tokenStart = input;
    
    while (count < 3) {
        key[count] = (tokenStart[0] != '\0') ? tokenStart[0] : 'a';
        count++;
        const char* delim = strchr(tokenStart, '-');
        if (delim == NULL)
            break;
        tokenStart = delim + 1;
    }
    while (count < 3)
        key[count++] = 'a';
    key[3] = '\0';
    return key;
}

struct LogResult {
    int originalLine;
    unsigned long long finalValue;
};

struct CompareLogResult {
    bool operator()(const LogResult &a, const LogResult &b) const {
            return a.finalValue < b.finalValue;
    }
};

int main(int argc, char *argv[]) {
    FILE *inputFile = fopen(argv[1], "r");
    unsigned long long *hostEncryptedNumbers = (unsigned long long*) malloc(MAX_LINES * sizeof(unsigned long long));
    
    char **hostMessages = (char**) malloc(MAX_LINES * sizeof(char*));
    for (int i = 0; i < MAX_LINES; i++) {
        hostMessages[i] = (char*) malloc(MAX_MESSAGE_LEN * sizeof(char));
    }
    
    int numEntries = 0;
    char lineBuffer[MAX_LINE_LEN + 1];
    char encryptedNumberStr[32];
    char messageText[MAX_MESSAGE_LEN];
    
    while (fgets(lineBuffer, sizeof(lineBuffer), inputFile) != NULL) {
        lineBuffer[strcspn(lineBuffer, "\n")] = '\0';
        
        sscanf(lineBuffer, "%*s %63s \"%255[^\"]\"", encryptedNumberStr, messageText);
        
        unsigned long long numberValue = strtoull(encryptedNumberStr, NULL, 10);
        hostEncryptedNumbers[numEntries] = numberValue;
        
        char *key = generateKey(messageText);
        strncpy(hostMessages[numEntries], key, MAX_KEY_LEN);
        hostMessages[numEntries][MAX_MESSAGE_LEN - 1] = '\0';
        
        numEntries++;
    }
    
    fclose(inputFile);

    char *hostMessageBuffer = (char*) malloc(numEntries * MAX_KEY_LEN * sizeof(char));
    for (int i = 0; i < numEntries; i++) {
        strcpy(&hostMessageBuffer[i * MAX_KEY_LEN], hostMessages[i]);
    }
    
    unsigned long long *deviceEncryptedNumbers;
    cudaMalloc((void**)&deviceEncryptedNumbers, numEntries * sizeof(unsigned long long));
    cudaMemcpy(deviceEncryptedNumbers, hostEncryptedNumbers, numEntries * sizeof(unsigned long long), cudaMemcpyHostToDevice);
    
    char *deviceMessageBuffer;
    cudaMalloc((void**)&deviceMessageBuffer, numEntries * MAX_KEY_LEN * sizeof(char));
    cudaMemcpy(deviceMessageBuffer, hostMessageBuffer, numEntries * MAX_KEY_LEN * sizeof(char), cudaMemcpyHostToDevice);
    
    unsigned long long *deviceFinalResults;
    cudaMalloc((void**)&deviceFinalResults, numEntries * sizeof(unsigned long long));
    
    int *deviceOriginalLineIndices;
    cudaMalloc((void**)&deviceOriginalLineIndices, numEntries * sizeof(int));
    
    int threadsPerBlock = 256;
    int numBlocks = (numEntries + threadsPerBlock - 1) / threadsPerBlock;
    processLogEntriesKernel<<<numBlocks, threadsPerBlock>>>(deviceEncryptedNumbers, deviceMessageBuffer, numEntries, deviceFinalResults, deviceOriginalLineIndices);
    cudaDeviceSynchronize();
    
    unsigned long long *hostFinalResults = (unsigned long long*) malloc(numEntries * sizeof(unsigned long long));
    int *hostOriginalLineIndices = (int*) malloc(numEntries * sizeof(int));
    cudaMemcpy(hostFinalResults, deviceFinalResults, numEntries * sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    cudaMemcpy(hostOriginalLineIndices, deviceOriginalLineIndices, numEntries * sizeof(int), cudaMemcpyDeviceToHost);

    thrust::host_vector<LogResult> logResults(numEntries);
    for (int i = 0; i < numEntries; i++) {
        logResults[i].originalLine = hostOriginalLineIndices[i] + 1;
        logResults[i].finalValue = hostFinalResults[i];
    }
    
    thrust::sort(logResults.begin(), logResults.end(), CompareLogResult());

    FILE *outputFile = fopen(argv[2], "w");

    for (int i = 0; i < numEntries; i++) {
        fprintf(outputFile, "%d %llu\n", logResults[i].originalLine, logResults[i].finalValue);
    }

    fclose(outputFile);
    
    free(hostEncryptedNumbers);
    for (int i = 0; i < numEntries; i++) {
        free(hostMessages[i]);
    }
    free(hostMessages);
    free(hostMessageBuffer);
    free(hostFinalResults);
    free(hostOriginalLineIndices);
    
    cudaFree(deviceEncryptedNumbers);
    cudaFree(deviceMessageBuffer);
    cudaFree(deviceFinalResults);
    cudaFree(deviceOriginalLineIndices);
    
    return 0;
}
